(()=>{document.querySelectorAll('button').forEach(b=>{const label=b.querySelector('[class*="navLabel"]')?.textContent.trim();if(label==='首页')b.onclick=()=>location.href='./';if(label==='历史对话')b.onclick=()=>location.href='./history.html';if(label==='我的作品')b.onclick=()=>location.href='./works.html';});})();
